import React, { useState } from "react";
import { addStudy, addNotice, uploadPDF } from "../services/api";

const AdminDashboard = () => {
  const [study, setStudy] = useState({ title: "", content: "" });
  const [notice, setNotice] = useState({ title: "", message: "" });
  const [pdf, setPdf] = useState(null);

  // 📚 Add Study
  const handleStudySubmit = async () => {
    if (!study.title || !study.content) {
      alert("Fill all fields");
      return;
    }

    try {
      await addStudy(study);
      alert("Study Material Added ✅");
      setStudy({ title: "", content: "" });
    } catch (err) {
      console.error(err);
      alert("Error adding study ❌");
    }
  };

  // 📢 Add Notice
  const handleNoticeSubmit = async () => {
    if (!notice.title || !notice.message) {
      alert("Fill all fields");
      return;
    }

    try {
      await addNotice(notice);
      alert("Notice Added ✅");
      setNotice({ title: "", message: "" });
    } catch (err) {
      console.error(err);
      alert("Error adding notice ❌");
    }
  };

  // 📄 Upload PDF
  const handlePDFUpload = async () => {
    if (!pdf) {
      alert("Select a PDF first");
      return;
    }

    try {
      await uploadPDF(pdf);
      alert("PDF Uploaded ✅");
      setPdf(null);
    } catch (err) {
      console.error(err);
      alert("Error uploading PDF ❌");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin Dashboard ⚙️</h2>

      {/* 📚 Study Section */}
      <div style={{ marginBottom: "20px" }}>
        <h3>Add Study Material</h3>

        <input
          type="text"
          placeholder="Title"
          value={study.title}
          onChange={(e) =>
            setStudy({ ...study, title: e.target.value })
          }
        />
        <br /><br />

        <textarea
          placeholder="Content"
          value={study.content}
          onChange={(e) =>
            setStudy({ ...study, content: e.target.value })
          }
        />
        <br /><br />

        <button onClick={handleStudySubmit}>Add Study</button>
      </div>

      <hr />

      {/* 📢 Notice Section */}
      <div style={{ marginBottom: "20px" }}>
        <h3>Add Notice</h3>

        <input
          type="text"
          placeholder="Title"
          value={notice.title}
          onChange={(e) =>
            setNotice({ ...notice, title: e.target.value })
          }
        />
        <br /><br />

        <textarea
          placeholder="Message"
          value={notice.message}
          onChange={(e) =>
            setNotice({ ...notice, message: e.target.value })
          }
        />
        <br /><br />

        <button onClick={handleNoticeSubmit}>Add Notice</button>
      </div>

      <hr />

      {/* 📄 PDF Upload Section */}
      <div>
        <h3>Upload PDF</h3>

        <input
          type="file"
          accept="application/pdf"
          onChange={(e) => setPdf(e.target.files[0])}
        />
        <br /><br />

        <button onClick={handlePDFUpload}>Upload PDF</button>
      </div>
    </div>
  );
};

export default AdminDashboard;
